{"path": "src/theme.ts", "content": "import { MD3LightTheme, configureFonts } from 'react-native-paper';

// Design tokens from DESIGN.md
export const space = (n: number) => n * 8; // 8dp grid

export const layout = {
  pagePadding: space(3), // 24dp
  maxContentWidth: 420, // updated to match design (max 420dp)
  maxWideWidth: 960,
  touchTarget: 48,
};

export const theme = {
  ...MD3LightTheme,
  roundness: 8,
  fonts: configureFonts({ config: { fontFamily: 'System' } }),
  colors: {
    ...MD3LightTheme.colors,
    // Primary (deep blue)
    primary: '#0061A4',
    onPrimary: '#FFFFFF',
    primaryContainer: '#CFE5FF',
    onPrimaryContainer: '#001D35',
    // Secondary (darker teal)
    secondary: '#015958',
    onSecondary: '#FFFFFF',
    secondaryContainer: '#C8F4EF',
    onSecondaryContainer: '#00201A',
    // Surfaces & background
    surface: '#FFFFFF',
    surfaceVariant: '#F2F2F2',
    background: '#F5F5F5',
    onSurface: '#212121',
    onSurfaceVariant: '#49454F',
    outline: '#79747E',
    // Disabled / placeholder
    disabled: '#E0E0E0',
    onDisabled: '#212121',
    placeholder: '#6F6F6F',
    // Status
    error: '#B00020',
    onError: '#FFFFFF',
    success: '#166534',
  },
};

export type AppTheme = typeof theme;
"}

{"path": "src/components/ui/FABAdd.tsx", "content": "import React, { useState } from 'react';
import { StyleSheet, View, Pressable, Text } from 'react-native';
import { Modal, Text as PaperText } from 'react-native-paper';
import { MaterialCommunityIcons } from '@expo/vector-icons';
import { theme, space } from '../../theme';
import { useNavigation, NavigationProp } from '@react-navigation/native';
import PrimaryButton from './PrimaryButton';

/**
 * Simple FAB that opens a modal with two options: Receipt and Mileage.
 * Implemented with Pressable to avoid nested interactive elements.
 */
export default function FABAdd() {
  const navigation = useNavigation<NavigationProp<any>>();
  const [open, setOpen] = useState(false);

  const toggle = () => setOpen((prev) => !prev);

  const goToReceipt = () => {
    navigation.getParent?.()?.navigate('ReceiptEntry');
    setOpen(false);
  };

  const goToMileage = () => {
    navigation.getParent?.()?.navigate('MileageEntry');
    setOpen(false);
  };

  return (
    <>
      {/* Main FAB */}
      <View style={styles.container} pointerEvents="box-none">
        <Pressable
          onPress={toggle}
          accessibilityLabel="Add"
          accessibilityRole="button"
          style={styles.fab}
        >
          <MaterialCommunityIcons name="plus" size={24} color={theme.colors.onSecondary} />
        </Pressable>
      </View>
      {/* Modal with options */}
      <Modal visible={open} onDismiss={toggle} contentContainerStyle={styles.modal}>
        <PaperText variant="titleMedium" style={{ marginBottom: 8 }}>
          Add entry
        </PaperText>
        {/* Use exact labels expected by the UI flow */}
        <PrimaryButton label="Receipt" variant="primary" onPress={goToReceipt} style={styles.button} />
        <PrimaryButton label="Mileage" variant="primary" onPress={goToMileage} style={styles.button} />
      </Modal>
    </>
  );
}

const styles = StyleSheet.create({
  container: { position: 'absolute', bottom: space(2), right: space(2), alignItems: 'center' },
  fab: {
    backgroundColor: theme.colors.secondary,
    width: 56,
    height: 56,
    borderRadius: 28,
    justifyContent: 'center',
    alignItems: 'center',
    elevation: 4,
  },
  modal: { backgroundColor: 'white', padding: 20, margin: 20, borderRadius: 8 },
  button: { marginTop: 8 },
});
"}

